std::string sender_app;
// Minted only by native macOS/ProcessSingleton URL ingress, never from a
// renderer, session restore, URL parameters, or persisted StartupTab data.
bool aux_native_external_receipt = false;

  for (auto& tab : startupTabs) {
    tab.sender_app = sender_app;
#if BUILDFLAG(ENABLE_AUX_BROWSER)
    tab.aux_native_external_receipt = true;
#endif
  }

#if BUILDFLAG(ENABLE_AUX_BROWSER)
  // After native privacy/profile selection, before opening anything. Preserve
  // ordered fallback through this exact native path with one-use receipt cleared.
  if (aux::routing::MaybeRouteExternalTabs(profile, tabs, base::BindRepeating(
      [](const StartupTab& tab, Profile* selected) {
        OpenStartupTabsInBrowserWithProfile(StartupTabs{tab}, selected);
      }))) return;
#endif
  // Use FindTabbedBrowser() to ensure URLs open in a normal tabbed browser

edits.find:
  Profiles last_opened_profiles;
#if !BUILDFLAG(IS_CHROMEOS)
  // On ChromeOS multiple profiles doesn't apply.
  // If no browser windows are open, i.e. the browser is being kept alive in
  // background mode or for other processing, restore |last_opened_profiles|.
  if (GlobalBrowserCollection::GetInstance()->GetSize() == 0) {
    last_opened_profiles =
        g_browser_process->profile_manager()->GetLastOpenedProfiles();
  }
#endif  // BUILDFLAG(IS_CHROMEOS)

  StartupBrowserCreator startup_browser_creator;
  startup_browser_creator.ProcessCmdLineImpl(
      command_line, cur_dir, chrome::startup::IsProcessStartup::kNo,
      {profile, mode}, last_opened_profiles);

edits.replace:
  auto continue_native = base::BindRepeating(
      [](const base::FilePath& cur_dir, StartupProfileMode mode,
         const base::CommandLine& native_command, Profile* selected) {
      Profiles last_opened_profiles;
    #if !BUILDFLAG(IS_CHROMEOS)
      // On ChromeOS multiple profiles doesn't apply.
      // If no browser windows are open, i.e. the browser is being kept alive in
      // background mode or for other processing, restore |last_opened_profiles|.
      if (GlobalBrowserCollection::GetInstance()->GetSize() == 0) {
        last_opened_profiles =
            g_browser_process->profile_manager()->GetLastOpenedProfiles();
      }
    #endif  // BUILDFLAG(IS_CHROMEOS)

      StartupBrowserCreator startup_browser_creator;
      startup_browser_creator.ProcessCmdLineImpl(
          native_command, cur_dir, chrome::startup::IsProcessStartup::kNo,
          {selected, mode}, last_opened_profiles);
      }, cur_dir, mode);
#if BUILDFLAG(ENABLE_AUX_BROWSER) && BUILDFLAG(IS_MAC)
  // This method is entered from the actual ProcessSingleton receipt, after
  // native profile selection. Renderer navigations never reach this seam.
  if (mode == StartupProfileMode::kBrowserWindow &&
      aux::routing::MaybeRouteExternalCommandLine(profile, command_line,
                                                 continue_native)) return;
#endif
  continue_native.Run(command_line, profile);
